-- supabase/seed.sql — 데모용 시드 데이터
-- docs/spec.md §7 요구사항: 교사 1명, 한빛초 5학년 2반, 학생 약 24명,
-- 데모 학생의 독후감 12개, 완독 3권, 7일 스트릭, 1,240 책갈피,
-- 반 랭킹 5개 반, 저작권 만료 도서 14권 + 본문 (spec.md §7 은 3~5권 — 초1~중3 전 학년을 채우려고 늘렸다).
--
-- 실행: supabase db reset (마이그레이션 0001~0005 적용 후 자동으로 이 파일이 돈다)
-- postgres 권한으로 돈다는 전제다 — auth.users 에 직접 넣기 때문이다.
-- 여러 번 돌려도 되게 만들었다: 맨 위에서 데모 데이터를 먼저 지우고 시작한다.
--
-- ─────────────────────────────────────────────────────────────────────────
-- 확인 필요 (→ 김민경) 2건
--
-- 1. 이해도 점수 92 / 88 / 95 는 현재 스키마로 만들 수 없다.
--    0003 의 comprehension_score() 는 3개 축(pass/weak/fail, same/shifted)에서
--    계산하므로 나올 수 있는 값이 {0, 17, 33, 50, 67, 83, 100} 뿐이다.
--    시드에서 임의의 숫자를 넣으면 v_teacher_student_progress 의 계산값과
--    화면 숫자가 따로 논다. 그래서 여기서는 100 / 83 / 100 으로 넣었다.
--    spec.md §7 의 92/88/95 를 그대로 쓰려면 verifications 에 수치 score 컬럼을
--    따로 두거나, 채점 루브릭을 더 잘게 쪼개야 한다. 스키마 결정 사항이라 남겨둔다.
--
-- 2. 저작권 만료 도서의 본문(book_contents.body)은 위키문헌에서 받은 실제 원문이다.
--    기억에 의존해 쓰지 않았다 — 실존 작가의 글에 틀린 텍스트가 박히면 안 된다.
--    '벙어리 삼룡이'(나도향)는 1925년 발표본이 옛 표기('될낙말낙할ᄯᅢ이닛가')라
--    초등·중학생이 읽을 수 없고 단어 사전도 찾지 못해, '동백꽃'(김유정)으로 바꿨다.
--    '물레방아'(나도향)는 표기는 깨끗하나 간통·살인이 소재라 아동 서재에 넣지 않았다.
-- ─────────────────────────────────────────────────────────────────────────

begin;

-- ── 0. 기존 데모 데이터 정리 ─────────────────────────
-- verifications.gap_id 가 on delete restrict 라 cascade 순서에 기대면 막힌다.
-- 의존 순서대로 명시적으로 지운다.

-- 데모 계정은 전부 @bookit.demo 메일이다. 중간 테이블 없이 서브쿼리로 고른다 (SQL Editor 호환).
delete from verifications      where student_id in (select id from auth.users where email like '%@bookit.demo');
delete from review_gaps        where review_id in (
  select id from reviews where student_id in (select id from auth.users where email like '%@bookit.demo'));
delete from reviews            where student_id in (select id from auth.users where email like '%@bookit.demo');
delete from points_ledger      where student_id in (select id from auth.users where email like '%@bookit.demo');
delete from streaks            where student_id in (select id from auth.users where email like '%@bookit.demo');
delete from genre_stamps       where student_id in (select id from auth.users where email like '%@bookit.demo');
delete from guardian_links     where student_id in (select id from auth.users where email like '%@bookit.demo');
delete from challenge_progress where student_id in (select id from auth.users where email like '%@bookit.demo');
delete from student_characters  where student_id in (select id from auth.users where email like '%@bookit.demo');
delete from reading_progress    where student_id in (select id from auth.users where email like '%@bookit.demo');
delete from checkpoints         where student_id in (select id from auth.users where email like '%@bookit.demo');
delete from challenges         where class_id in (
  select id from classes where teacher_id in (select id from auth.users where email like '%@bookit.demo'));
-- 고정 id 로 넣는 행은 id 로도 지운다 (시즌 챌린지는 class_id 가 null 이라 위 조건에 안 걸린다).
delete from challenges         where id::text like '0000e0%';
delete from classes            where id::text like '0000d0%';
delete from class_members      where student_id in (select id from auth.users where email like '%@bookit.demo');
delete from classes            where teacher_id in (select id from auth.users where email like '%@bookit.demo');
delete from profiles           where id in (select id from auth.users where email like '%@bookit.demo');
delete from auth.users         where id in (select id from auth.users where email like '%@bookit.demo');

delete from book_contents where book_id in (
  select id from books where id::text like '0000b0%'
     or id::text like '0000b1%');
-- books 는 지우지 않는다. reviews.book_id 가 on delete restrict(0003) 라 실제 계정이
-- 시드 책으로 독후감을 하나라도 쓰면 여기서 막힌다. §1 이 같은 id 로 upsert 한다.

-- ── 1. 도서 ──────────────────────────────────────────
-- 앞의 4권과 이 섹션 끝의 10권이 저작권 만료 도서(책잇 서재에서 읽힘), 나머지는 일반 도서.
-- 저작권 만료 도서의 태그는 GENRE_TAGS(src/modules/ai/schema.ts)만 쓴다.
-- cover_url 은 비워둔다 — 실제 표지는 알라딘 API image URL 에서 온다 (CLAUDE.md §10).

-- ISBN 은 국립중앙도서관 서지 API 로 확인한 실제 번호다 (2026-09-15). 예전 시드의 번호는
-- 지어낸 것이라 검색 결과의 다른 책(아몬드 청소년판 = 옛 '완득이' 번호)과 겹쳐, 검색한
-- 책이 엉뚱한 시드 책으로 바뀌어 보였다. 'harry'·'squirrel' 픽스처는 ISBN 을 두지 않는다.
-- 검색이 먼저 같은 ISBN 을 저장했을 수 있어(unique) 시드 밖 행의 번호는 비운다.
update books set isbn13 = null
 where id::text not like '0000b0%'
   and isbn13 in ('9788936434267','9788936456085','9791160946635','9791128218705','9788915100275',
                  '9788900282931','9788997173587','9788987721095','9788936477721');

insert into books (id, isbn13, title, author, publisher, tags,
                   target_grade_min, target_grade_max, is_public_domain,
                   library_url, aladin_url) values
  ('0000b001-0000-4000-8000-000000000001', null, '운수 좋은 날',        '현진건', null, '{"고전","사회"}',        7, 9, true,  null, null),
  ('0000b002-0000-4000-8000-000000000002', null, '메밀꽃 필 무렵',      '이효석', null, '{"고전","가족"}',        7, 9, true,  null, null),
  ('0000b003-0000-4000-8000-000000000003', null, '봄봄',                '김유정', null, '{"고전","가족"}', 6, 9, true,  null, null),
  ('0000b004-0000-4000-8000-000000000004', null, '동백꽃',              '김유정', null, '{"고전","성장소설"}', 5, 9, true,  null, null),

  ('0000b005-0000-4000-8000-000000000005', '9788936434267', '아몬드',        '손원평',   '창비',       '{"성장소설"}',       6, 9, false, null, null),
  ('0000b006-0000-4000-8000-000000000006', '9788936456085', '완득이',        '김려령',   '창비',       '{"성장소설"}',       6, 9, false, null, null),
  ('0000b007-0000-4000-8000-000000000007', '9791160946635', '마당을 나온 암탉', '황선미', '사계절',     '{"동화","성장소설"}',           3, 6, false, null, null),
  ('0000b008-0000-4000-8000-000000000008', '9791128218705', '나의 라임오렌지나무', '조제 마우루', '아람', '{"성장소설"}',     5, 8, false, null, null),
  ('0000b009-0000-4000-8000-000000000009', '9788915100275', '어린 왕자',      '생텍쥐페리', '삼성출판사', '{"고전"}', 4, 9, false, null, null),
  ('0000b010-0000-4000-8000-000000000010', '9788900282931', '동물농장',       '조지 오웰',  '두산동아',   '{"고전","사회"}', 7, 9, false, null, null),
  ('0000b011-0000-4000-8000-000000000011', null, 'harry',         '데모 저자',  '데모출판',  '{"판타지"}',     4, 8, false, null, null),
  ('0000b012-0000-4000-8000-000000000012', '9788997173587', '갈매기의 꿈',    '리처드 바크', '와니북스', '{"성장소설"}',     5, 9, false, null, null),
  ('0000b013-0000-4000-8000-000000000013', '9788987721095', '우리들의 일그러진 영웅', '이문열', '다림', '{"사회"}',      7, 9, false, null, null),
  ('0000b014-0000-4000-8000-000000000014', null, 'squirrel',      '데모 저자',  '데모출판',  '{"과학"}',           5, 8, false, null, null),
  ('0000b015-0000-4000-8000-000000000015', '9788936477721', '몽실 언니',      '권정생',    '창비',      '{"역사"}',       5, 8, false, null, null)
on conflict (id) do update set
  isbn13 = excluded.isbn13, title = excluded.title, author = excluded.author,
  publisher = excluded.publisher, tags = excluded.tags,
  target_grade_min = excluded.target_grade_min, target_grade_max = excluded.target_grade_max,
  is_public_domain = excluded.is_public_domain,
  library_url = excluded.library_url, aladin_url = excluded.aladin_url;

-- 저작권 만료 도서 본문. 위키문헌(ko.wikisource.org)에서 받은 원문이다.
-- 세 작가 모두 사후 70년이 지나 저작권이 만료됐다 — 현진건(1943)·이효석(1942)·김유정(1937).
--
-- 단편이라 원래 장 구분이 없다. 글자 수가 고르도록 3등분하되 문단 중간에서 자르지 않았다.
-- 서재 화면이 장 단위로 읽히는지 확인할 수 있는 최소 구성이다.
insert into book_contents (book_id, chapter_no, title, body) values
  ('0000b001-0000-4000-8000-000000000001', 1, '1장',
   '새침하게 흐린 품이 눈이 올 듯하더니 눈은 아니 오고 얼다가 만 비가 추적추적 내리었다.

이날이야말로 동소문 안에서 인력거꾼 노릇을 하는 김 첨지에게는 오래간만에도 닥친 운수 좋은 날이었다. 문안에(거기도 문밖은 아니지만) 들어간답시는 앞집 마나님을 전찻길까지 모셔다 드린 것을 비롯으로 행여나 손님이 있을까 하고 정류장에서 어정어정하며 내리는 사람 하나하나에게 거의 비는 듯한 눈결을 보내고 있다가 마침내 교원인 듯한 양복장이를 동광학교(東光學校)까지 태워다 주기로 되었다.

첫번에 삼십 전, 둘째 번에 오십 전 - 아침 댓바람에 그리 흔치 않은 일이었다. 그야말로 재수가 옴붙어서 근 열흘 동안 돈 구경도 못한 김 첨지는 십 전짜리 백통화 서 푼, 또는 다섯 푼이 찰깍하고 손바닥에 떨어질 제 거의 눈물을 흘릴 만큼 기뻤었다. 더구나 이날 이때에 이 팔십 전이라는 돈이 그에게 얼마나 유용한지 몰랐다. 컬컬한 목에 모주 한 잔도 적실 수 있거니와 그보다도 앓는 아내에게 설렁탕 한 그릇도 사다줄 수 있음이다.

그의 아내가 기침으로 쿨럭거리기는 벌써 달포가 넘었다. 조밥도 굶기를 먹다시피 하는 형편이니 물론 약 한 첩 써 본 일이 없다. 구태여 쓰려면 못 쓸 바도 아니로되 그는 병이란 놈에게 약을 주어 보내면 재미를 붙여서 자꾸 온다는 자기의 신조(信條)에 어디까지 충실하였다. 따라서 의사에게 보인 적이 없으니 무슨 병인지는 알 수 없으되 반듯이 누워 가지고, 일어나기는새로 모로도 못 눕는 걸 보면 중증은 중증인 듯. 병이 이대도록 심해지기는 열흘 전에 조밥을 먹고 체한 때문이다.

그때도 김 첨지가 오래간만에 돈을 얻어서 좁쌀 한 되와 십 전짜리 나무 한 단을 사다 주었더니 김 첨지의 말에 의지하면 그 오라질 년이 천방지축(天方地軸)으로 남비에 대고 끓였다. 마음은 급하고 불길은 닿지 않아 채 익지도 않은 것을 그 오라질 년이 숟가락은 고만두고 손으로 움켜서 두 뺨에 주먹덩이 같은 혹이 불거지도록 누가 빼앗을 듯이 처박질 하더니만 그날 저녁부터 가슴이 땅긴다, 배가 켕긴다고 눈을 홉뜨고 지랄병을 하였다. 그때 김 첨지는 열화와 같이 성을 내며,

“에이, 오라질 년, 조롱복은 할 수가 없어, 못 먹어 병, 먹어서 병, 어쩌란 말이야! 왜 눈을 바루 뜨지 못해!”하고 김 첨지는 앓는 이의 뺨을 한 번 후려갈겼다. 홉뜬 눈은 조금 바루어졌건만 이슬이 맺히었다. 김 첨지의 눈시울도 뜨끈뜨끈하였다.

이 환자가 그러고도 먹는 데는 물리지 않았다. 사흘 전부터 설렁탕 국물이 마시고 싶다고 남편을 졸랐다.

“이런 오라질 년! 조밥도 못 먹는 년이 설렁탕은, 또 처먹고 지랄병을 하게.”라고, 야단을 쳐보았건만, 못 사주는 마음이 시원치는 않았다.

인제 설렁탕을 사줄 수도 있다. 앓는 어미 곁에서 배고파 보채는 개똥이(세 살먹이)에게 죽을 사줄 수도 있다. — 팔십 전을 손에 쥔 김 첨지의 마음은 푼푼하였다. 그러나 그의 행운은 그걸로 그치지 않았다. 땀과 빗물이 섞여 흐르는 목덜미를 기름주머니가 다 된 왜목 수건으로 닦으며, 그 학교 문을 돌아나올 때였다. 뒤에서 <인력거!> 하고 부르는 소리가 난다. 자기를 불러 멈춘 사람이 그 학교 학생인 줄 김 첨지는 한 번 보고 짐작할 수 있었다. 그 학생은 다짜고짜로, “남대문 정거장까지 얼마요?”라고, 물었다.

아마도 그 학교 기숙사에 있는 이로 동기방학을 이용하여 귀향하려 함이리라. 오늘 가기로 작정은 하였건만 비는 오고, 짐은 있고 해서 어찌할 줄 모르다가 마침 김 첨지를 보고 뛰어나왔음이리라. 그렇지 않으면 왜 구두를 채 신지 못해서 질질 끌고, 비록 <고구라> 양복일망정 노박이로 비를 맞으며 김 첨지를 뒤쫓아 나왔으랴.

“남대문 정거장까지 말씀입니까.”하고 김 첨지는 잠깐 주저하였다. 그는 이 우중에 우장도 없이 그 먼 곳을 철벅거리고 가기가 싫었음일까? 처음 것, 둘째 것으로 그만 만족하였음일까? 아니다, 결코 아니다. 이상하게도 꼬리를 맞물고 덤비는 이 행운 앞에 조금 겁이 났음이다. 그리고 집을 나올 제 아내의 부탁이 마음에 켕기었다. — 앞집 마나님한테서 부르러 왔을 제 병인은 그 뼈만 남은 얼굴에 유일의 생물 같은 유달리 크고 움폭한 눈에 애걸하는 빛을 띠우며, “오늘은 나가지 말아요. 제발 덕분에 집에 붙어있어요. 내가 이렇게 아픈데……”라고, 모기 소리같이 중얼거리고 숨을 걸그렁걸그렁 하였다.

그때에 김 첨지는 대수롭지 않은 듯이, “압다, 젠장맞을 년, 별 빌어먹을 소리를 다 하네. 맞붙들고 앉았으면 누가 먹여 살릴 줄 알아.”하고, 훌쩍 뛰어나오려니까 환자는 붙잡을 듯이 팔을 내저으며, “나가지 말라도 그래, 그러면 일찌기 들어와요.”하고, 목메인 소리가 뒤를 따랐다.

정거장까지 가잔 말을 들은 순간에 경련적으로 떠는 손, 유달리 큼직한 눈, 울 듯한 아내의 얼굴이 김 첨지의 눈앞에 어른어른하였다. “그래 남대문 정거장까지 얼마란 말이요?”하고 학생은 초조한 듯이 인력거꾼의 얼굴을 바라보며 혼잣말같이, “인천 차가 열 한 점에 있고, 그 다음에는 새로 두 점이든가.”라고, 중얼거린다.

