  ('0000b105-0000-4000-8000-000000000105', 1, '1장',
   '기다리던 설이 와서 기뻤습니다. 여러분! 과세나 잘들 하셨습니까? 이번 새해는 쥐의 해니까 이번에는 특별히 쥐에 관계 있는 이야기를 하겠습니다.

