촌(마을) 등 뒤 조그마한 냇가의 경치, 멀리 등성이 위로 초가집 지붕이 두 셋 보이고, 그 등성이 아래로는 조그만 냇물이 보이며, 그 내 위에는 다리가 놓여 있다. (막이 열림.)

