“오냐! 어찌하여 내가 내 몸을 구해낸 사람을 내 손으로 죽이는 까닭을 이야기해 주마. 자세히 들어라! 내가 지금부터 일천 팔백여 년 전 옛적에, 신령님 명령을 복종하지 않고 거역한 죄로, 신령님이 나를 잡아서 연기로 만들어서 이 구리 항아리 속에 잡아 넣고, 다시 못나오도록 납을 끓여서 주둥이를 막고, 그 항아리를 저 바다에 집어 던졌다. 그래 나는 맨 처음에 이 항아리 속에 갇힌 채 바다 속에서 맹세하기를, 누구든지 백 년 안에 내 몸을 이 항아리에서 나가게 해 주면, 그 사람을 이 나라에서 제일 가는 부자가 되게 해 주겠다고 하였단다. 그러나, 백 년이 다 지나도록 한 놈도 나를 구해 내 준 사람은 없구나. 그래 다시 이백 년 안에 나를 구해 내어 준 사람에게는 이 세상에서 제일 가는 보물을 얻게 해 주겠다고 맹세하였단다. 그러나, 이백 년이 또 그냥 지나갔으므로 또 다시 삼백 년 안에 구해 준 사람에게는 어느 나라 왕이 되게 해 주고, 또 늙어 죽을 때까지 날마다 하루에 세 가지씩 소원을 이루어 주겠다고 맹세했단다. 그러나, 삼백 년은커녕 사백 년, 오백 년이 지나도록 아무 놈도 구해 내 주는 놈이 없었단다. 그래 나도 골이 나서, 인제는 어느 때든지 나를 이 항아리에서 구해 내는 놈은 잡아 죽이겠다고 맹세했단다. 그런데 일천 년, 일천 오백 년, 일천 팔백 년이 지난 오늘, 네가 나를 구해내었으니까, 그래 너를 죽인단 말이다. 그런데 다만 한 가지 죽이는 방법은 너의 소원대로 해 줄 터이니, 어떻게 죽여 주는 것이 제일 좋은지 말해 보아라.”

