“그럼 할 수 없습니다. 잠자코 죽지요. 죽여 주십시오. 그러나, 어떻게 죽여 달라는 소원을 말씀하기 전에, 한가지 여쭈어 볼 말씀이 있습니다.”

“무엇이냐? 무어냐?”

“당신은 한 번 결심하신 것을 그렇게 변하지 않으시는 거와 같이, 거짓 말씀도 안 하시겠지요…….”

