“암만해도 믿어지지 않습니다. 한 번 그 증거를 보여 주시면 꼭 믿겠습니다.”

마귀는 답답스러이 화증을 벌컥 내면서,

“아따! 미련한 놈! 자아, 보아라. 이렇게 내 몸이 연기가 되어 가지고…….”

하면서, 그 큰 몸이 검은 연기로 변하더니 온 하늘로 뭉게뭉게 피어 올랐다가, 다시 솔솔 항아리 주둥이로 기어 들어갔습니다. 한참 동안이나 걸려서,

