  ('0000b124-0000-4000-8000-000000000124', 1, '1장',
   '옛날인지 지금인지 팔달이란 젊은이가, 뒷집 혹부리 영감님을 찾아와서,

“뒷집 아저씨, 오늘 나쁘지 않으십니까?”

“응, 별로 나쁜 일 없네. 왜 그러나?”

“집에서 물을 담아 둘 데가 없다고, 물독을 하나 사 오라 하는데, 제가 잘 살 줄 알아야지요. 아저씨께서 같이 가셔서, 하나 사 주십시오. 스무 동이의 물이 드는 것을 사 오래요.”

“응, 그렇지. 처음 사는 사람이 사면 속여서 비싸게 파는 법일세……. 내가 가서 싸게 사 줄 것이니, 나만 따라오게. 스무 동이 물이 드는 독이라지?…….”

두 사람이 나섰습니다. 동관 항아리 파는 옹기점으로 가면서 혹부리 영감이,

“여보게, 물건 흥정이란 잘하는 법이 따로 있는 것이니 자네는 입 다물고, 아무 말 말고 보기만 하게.”

“예, 아무 날 안할 터입니다.”

약속을 단단히 하고, 큰 한길 옹기점에까지 왔습니다. 혹부리 영감이,

영감 “여보, 주인! 독 하나 삽시다. 열 동이의 물이 드는 독 하나에 얼마요?”

하므로 팔달이가 열 동이의 물이 드는 독이 아니라, 스무 동이의 물이 드는 독이라고 이르려 하니까, 영감이,

“쉬!”

하고, 말을 못하게 합니다.

주인이 나와서, 거기 엎어 놓은 독을 내놓고,

주인 “예, 이것이 열 동이의 물이 드는 독이올시다. 3원 50전만 내십시오.”

영감 “여보, 50전은 그만 두고, 3원에 파시오. 내가 사는 것도 아니고, 저 사람이 사 달라 하니까, 싸게 사 주마고 여기까지 데리고 온 것이니, 3원에 파시오.”

주인 “그러면 밑지지만 3원에 드리지요.”

그래 혹부리 영감은 팔달이에게서 3원을 받아 주인에게 주고 열 동이의 물이 드는 독을 사서 새끼로 얽어 작대기에 꿰어 들고, 팔달이는 앞을 들고, 영감은 뒤를 들고 돌아갑니다. 그러나 팔달이는 투덜투덜하며,

팔달 “스무 동이의 물이 드는 독을 사 달라니까, 왜 열 동이의 물이 드는 독을 샀습니까?”

영감 “아따 이 사람아, 잠자코 내가 가자는 대로 가세그려……. 한 바퀴만 돌아가면 이것이 스무 동이 물이 드는 독이 된다네.”

팔달 “어떻게 열 동이짜리가 스무 동이가 되어요? 공연히 잘못 샀지요.”

영감 “글쎄, 가만히 있다가 스무 동이짜리로 변하는 것만 보게그려.”

욱신각신 떠드는 동안에 어느 틈에 골목 하나를 휘돌아서, 아까 그 옹기점 앞으로 도로 왔습니다. 팔달이가 이상하여,

팔달 “에그, 그 옹기점으로 도로 왔습니까?”

영감 “글쎄, 가만히 있어…….”

옹기점 주인이 보니까, 아까 독 사 간 사람이 그 독을 도로 들고 온지라 이상하여,

주인 “왜 도로 오셨습니까?”

영감 “그런 게 아니라, 이 사람이 애초에 스무 동이짜리 독을 사 달라 한 것을, 내가 잊어버리고 열 동이짜리를 사 가지고 갔소. 그래 이것은 그만두고, 스무 동이짜리를 사려고 도로 왔소그려. 스무 동이짜리 독이 있나요? 값은 얼마구요?”

주인 “예, 있습니다. 여기 이 큰 독이 스무 동이짜리입니다. 값은 7원을 주셔야 합니다. 갑절이니까요.”

영감 “여보, 갑절이라니, 3원의 갑절 6원에 파시오. 그럼 옳지 않소? 6원요.”

주인 “그러십시오. 아까 3원에 팔았으니까, 할 수 없습니다. 6원에 가져 가십시오.”

혹부리 영감이 가지고 온 열 동이 독을 끌러 놓고 하는 말이,

영감 “자, 3원짜리 독을 받으시오. 이 큰 독은 6원이라지요? 그런데, 이 3원짜리 독을 당신이 받고요. 그러면 6원에서 3원 남았지요”

주인 “예, 3원 남습니다.”

영감 “그런데, 내가 아까 처음에 지전으로 3원 준 것이 있지요? 그 3원하고 이 독 3원하고 6원 맞지요.”

주인 “예, 이 3원짜리 독하고, 아까 그 돈 3원하고, 예, 예, 6원 맞습니다. 예.”

영감 “그러면, 나는 가오. 평안히 계시오.”

하고, 이번에는 큰 독을 매어 작대기에 꿰어, 앞뒤에서 들고 휘적휘적 걸어 가면서,

영감 “여보게, 주인놈이 혹시 쫓아올지도 모르니, 빨리 가세.”

하는데, 벌써 주인이,

“여보, 여보!”

하고, 소리쳐 부르는 고로 할 수 없이 도로 갔습니다.

영감 “왜 부르시오.”

주인 “암만해도 3원을 덜 받았습니다. 3원을 더 내십시오.”

영감 “허허, 당신이 셈칠 줄을 모르는구려.”

하고, 독을 땅에 내려 놓고,

영감 “내가 다시 똑똑히 쳐 줄 터이니, 수판을 내어 들고 놓아 보시오.”

주인 “예, 수판을 들었습니다.”

영감 “내가 6원 내면 맞지요?”

주인 “예!”

영감 “내가 맨 처음 지전 일 원짜리 3장을 당신 드렸지요?”

주인 “예! 받았습니다.”

영감 “그럼, 그 수판에 3원을 놓으시오.”

주인 “예, 3원 놓았습니다.”

영감 “나중에 도로 와서, 큰 독을 살 때에 내가 3원에 샀던 독을 그냥 당신에게 주었지요. 3원짜리 독을 분명히 받았지요”

주인 “예, 독도 받았습니다.”

영감 “그럼, 아까 그 3원에 또 3원 놓으시오.”

주인 “예, 놓았습니다.”

영감 “그럼, 도합 얼마요?”

주인 “6원입니다.”

영감 “그래, 내가 6원 내지 않았소?”

주인 “글쎄요, 6원이 맞기는 맞는데…….”

영감 “6원이 또 틀립니까?”

주인 “아니오. 맞기는 맞습니다.”

영감 “그런데 왜 그러시오. 나는 가오.”

주인 “예, 안녕히 가십시오.”

하였으나, 암만 생각해 보아도 손에 쥔 돈은 단 3원뿐이므로 까닭을 몰라 머리를 득득 긁으니까, 그 때 혹부리 영감이 가다가 말고 돌아서서, 가게를 들여다보고 큰 소리로,

“여보. 그게 옹깃셈이라는 거요. 그것도 모르고 옹기 장사를 한단 말요!”

하더랍니다.

여러분, 여러분 중에는 그 옹기 장사 같은 어리석은 사람이 없습니까? 하하하하.'),
  ('0000b125-0000-4000-8000-000000000125', 1, '1장',
   '센 강을 건너가는 나룻배에 조그만 어린 거지 두 사람이 여러 손님 옆 한구석에 앉아 있습니다.

한 사람은 열 살쯤 된 소년이고, 한 사람은 열한 살 되어 보이는 소녀인데 둘은 서로 모르는 사이였으나 각각 남의 문 앞으로 노래를 부르면서 돈을 구걸하러 다니는 같은 신세였습니다.

그래 오늘도 온종일 돌아다니다가 저녁이 되어 강을 건너 지금 집으로 돌아가는 것이었습니다. 몹시 피곤하여 푸른 얼굴을 힘없이 늘어뜨리고 있던 소녀는 치마를 들치고 주머니에서 오늘 얻은 돈을 꺼내서 치마 위에 늘어놓더니 그것을 헤이기 시작하였습니다. 불쌍하디 불쌍한 소녀의 가련한 눈이 이 때에만 잠깐 기쁜 빛이 돌았습니다.

1전, 2전, 3전, 4전 세는 소리를 듣고 옆에 근심스럽게 고개를 숙이고 있던 소년도 고개를 돌이켜 그것을 부럽게 보았습니다.

“22전, 24전, 25전…… 그리고 이 번쩍번쩍하는 50전짜리 새 은전…… 모두 75전이다…….”

‘어이휴!’

하고 근심만 하는 소년이 그것을 보고 탄식하는 소리를 듣고 소녀는 동전과 은전을 따로 쥐고,

“이 은전은 까만 옷을 입은 점잖은 마님(부인)이 주셨단다. 불쌍하다고 나를 번쩍 들어서 껴안아까지 주시고, 그런데 너는 오늘 얼마나 벌었니?”

“나는 오늘 한 푼도 못 벌었단다.”

소년은 슬픈 소리로 대답하였습니다.

“에그, 그럼 집에 들어가면 두들겨 맞겠구나……. 그래 그렇게 걱정을 하고 있니?”

“아니, 나는 매는 안 맞는단다. 너는 매를 맞니? 두들겨 맞아?”

“그렇단다. 돈을 많이 벌어 가지 않으면 굵다란 나무때기로 맞는단다.”

“아이고, 그럼 자주 얻어맞겠구나! 나는 우리 어머니하고 같이 있는데 돈은 못 벌어도 그냥 꾸지람만 하지 때리지는 않는단다. 어머니하고 늘 같이 다녀도 이 바이올린 켜면 어머니가 거기 맞춰서 노래를 부르면 사람들이 돈을 많이 준단다. 그런데 오늘은 나 혼자 바이올린만 켜니까 돈을 한 푼도 못 벌었단다.”

“그럼, 오늘은 왜 어머니하고 같이 나오지 않았니?”

그때에 어린 소년은 고개를 푹 숙이는데 그 눈에서 눈물이 뚝뚝 떨어졌습니다.

“우리 어머니는 병이 나서 앓고 계신단다.”

소녀는 아무 말이 없이 한참이나 잠자코 있더니 자기 손에 들고 있던 돈 75전을 소년의 앞에 내어밀었습니다.

“이 돈을 갖다가 병든 어머니께 드려라.”

“아니, 그만두어라. 네가 얻어맞게?”

“아니다, 괜찮다. 가지고 가거라. 나는 날마다 얻어맞으니까 괜찮다……. 너의 어머니의 병을 고쳐야 살지……. 자아 옛다.”

소년의 눈에서도 소녀의 눈에서도 눈물이 펑펑 쏟아졌습니다.

“싫다. 나 때문에 너의 집에 가서 두들겨 맞으면 어떻게 하니……. 그냥 가지고 가거라.”

하고 소년은 그 돈을 영영 받지 않았습니다. 소녀도 하는 수 없이 돈을 도로 넣고,

